gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLMatrix(object):
    def __init__(self, data: list[list[float]]):
        self.mat = gsl.gsl_matrix_alloc(len(data), len(data[0]))
        for i in range(len(data)):
            for j in range(len(data[0])):
                self.mat[i][j] = data[i][j]
    def __str__(self):
        return str(self.mat)
    def get_values(self) -> list[list[float]]:
        result = []
        for i in range(len(self.mat)):
            row = []
            for j in range(len(self.mat[0])):
                row.append(self.mat[i][j])
            result.append(row)
        return result
    def __del__(self):
        gsl.gsl_matrix_free(self.mat)

class GSLVector(object):
    def __init__(self, data: list[float]):
        self.vec = gsl.gsl_vector_alloc(len(data))
        for i in range(len(data)):
            self.vec[i] = data[i]
    def get_values(self) -> list[float]:
        return [self.vec[i] for i in range(len(self.vec))]
    def __del__(self):
        gsl.gsl_vector_free(self.vec)

def numpy_to_gsl_matrix(np_array: list[list[float]]) -> GSLMatrix:
    return GSLMatrix(np_array)
def numpy_to_gsl_vector(np_array: list[float]) -> GSLVector:
    return GSLVector(np_array)
def compute_gensymm_eigenvalues(A: GSLMatrix, B: GSLMatrix) -> GSLVector:
    workspace = gsl.gsl_eigen_gensymm_alloc(len(A.mat))
    gsl.gsl_eigen_gensymm_workspace_set(workspace, A.mat, B.mat)
    eigenvalues = gsl.gsl_eigen_gensymm_solve(workspace)
    return GSLVector([eigenvalues[i].eigenvalue for i in range(len(eigenvalues))])
def generalized_symmetric_eigenvalues(A: list[list[float]], B: list[list[float]]) -> list[float]:
    try:
        A = numpy_to_gsl_matrix(A)
        B = numpy_to_gsl_matrix(B)
        eigenvalues = compute_gensymm_eigenvalues(A, B)
        return eigenvalues.get_values()
    except Exception as e:
        print(f"Error: {e}")
        return []

