import numpy as np

def numpy_to_gsl_matrix_complex(np_array):
  from gsl import * 
  m = gsl_matrix_complex_alloc(np_array.shape[0], np_array.shape[1])
  for i in range(np_array.shape[0]):
    for j in range(np_array.shape[1]):
      m[i,j] = np_array[i,j]
  return m

def gsl_vector_to_numpy(gsl_vector, size):
  vec = (ctypes.c_double * size)() 
  for i in range(size):
    vec[i] = gsl_vector_get(gsl_vector, i)
  return np.array(vec)

def compute_eigenvalues(A, B):
  gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
  cblas = ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
  try:
    A_gsl = numpy_to_gsl_matrix_complex(A)
    B_gsl = numpy_to_gsl_matrix_complex(B)

    eigenvalues_gsl = gsl.gsl_eigen_genherm(A_gsl, B_gsl)
    eigenvalues_np = gsl_vector_to_numpy(eigenvalues_gsl.ev, eigenvalues_gsl.size)
    return eigenvalues_np
  except OSError as e:
    print(f'Error loading GSL libraries: {e}')
    return None

