class GSLFunction:
    def __init__(self, func):
        self.func = func

    def call(self, x, params=None):
        return self.func(x)

def compute_chebyshev_approximations() -> List[Tuple[float, float, float, float]]:
    libgslcblas = ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

    def f(x, params):
        return x**2 + 1

    func = GSLFunction(f)

x_values = gsl.gsl_vector_alloc(10000)
    for i in range(10000):
      x_values[i] = i / 9999

    cheb_alloc = gsl.gsl_cheb_alloc(10000, 10000)
    cheb_init = gsl.gsl_cheb_init(cheb_alloc, func.call, x_values)
    r10 = [0] * 10000
    r40 = [0] * 10000
    for i in range(10000):
      gsl.gsl_cheb_eval_n(cheb_init, x_values[i], r10[i])
      gsl.gsl_cheb_eval(cheb_init, x_values[i], r40[i])

    results = [(x / 9999, func.call(x / 9999, None), r10[i], r40[i]) for i in range(10000)]
    return results

