    def __init__(self, data):
        self.data = (c_double * (len(data) * len(data[0])))(*data)

    def __repr__(self):
        return str([[x for x in row] for row in [list(self.data[i::len(data[0])]) for i in range(len(data[0]))]])

class GSLMultifitFunctionFDF(object):
    def __init__(self, func):
        self.func = func

    def fdf(self, x, wts, f, n, p):
        x_gsl = GSLVector(x)
        wts_gsl = GSLVector(wts)
        f_gsl = GSLVector(f)
        J = gsl.gsl_multifit_fdfsolver_dif_df(x_gsl, wts_gsl, f_gsl, n, p)

        return [list(J[i::p]) for i in range(p)]



