class GSLVector(object):
    def __init__(self, size):
        self._ptr = gsl.gsl_vector_alloc(size)
    def __del__(self):
        gsl.gsl_vector_free(self._ptr)
    def get(self, i):
        return gsl.gsl_vector_get(self._ptr, i)
    def set(self, i, value):
        gsl.gsl_vector_set(self._ptr, i, value)

class GSLMultiminFunctionFDF(object):
    def __init__(self, f, df):
        self.f = f
        self.df = df

    def __call__(self, x):
        return self.f(x), self.df(x)

GSLMultiminFDFMinimizerType = gsl.gsl_multimin_fdfminimizer_type_bfgs2

def minimize(f, df, x0, tol=1e-6):
    n = len(x0)
    x = GSLVector(n)
    for i in range(n):
        x.set(i, x0[i])

    minimizer = gsl.gsl_multimin_fdfminimizer_alloc(GSLMultiminFDFMinimizerType(), n)
    function = GSLMultiminFunctionFDF(f, df)

    status = gsl.gsl_multimin_fdfminimizer_apply(minimizer, function, x)
    x_star = []
    for i in range(n):
        x_star.append(x.get(i))

    return x_star

