    x_gsl = gsl_vector(data=ctypes.cast(ctypes.array('d' * len(x)) , ctypes.POINTER(ctypes.c_double)), size=len(x), stride=1)
    y_gsl = gsl_vector(data=ctypes.cast(ctypes.array('d' * len(y)) , ctypes.POINTER(ctypes.c_double)), size=len(y), stride=1)
