def matrix_to_gsl(matrix):
    return gsl.gsl_matrix_alloc(len(matrix), len(matrix[0]))

def vector_to_gsl(vector):
    return gsl.gsl_vector_alloc(len(vector))

def gsl_matrix_to_list(matrix):
    rows = matrix.size1
    cols = matrix.size2
    result = [[0 for _ in range(cols)] for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            result[i][j] = matrix[i, j]
    return result

def gsl_vector_to_list(vector):
    size = vector.size
    result = [0 for _ in range(size)]
    for i in range(size):
        result[i] = vector[i]
    return result

gsl_linalg_QL_decomp = gsl.gsl_linalg_QL_decomp
gsl_linalg_QL_unpack = gsl.gsl_linalg_QL_unpack
def ql_decomposition_and_unpack(A, tau):
    A_gsl = matrix_to_gsl(A)
    tau_gsl = vector_to_gsl(tau)
    m, n = A_gsl.size1, A_gsl.size2
    Q = gsl.gsl_matrix_alloc(m, m)
    L = gsl.gsl_matrix_alloc(m, n)
    gsl_linalg_QL_decomp(A_gsl, tau_gsl, Q, L)
    return gsl_matrix_to_list(Q), gsl_matrix_to_list(L)

