class GslRstatQuantileWorkspace:
    def __init__(self):
        self.workspace = libgsl.gsl_rstat_quantile_alloc(1) 

    def reset(self):
        libgsl.gsl_rstat_quantile_reset(self.workspace)

    def add_values(self, values: List[float]):
        for value in values:
            libgsl.gsl_rstat_quantile_add(self.workspace, value)

    def get_quantile(self, p: float) -> float:
        return libgsl.gsl_rstat_quantile_get(self.workspace, p)

    def free(self):
        libgsl.gsl_rstat_quantile_free(self.workspace)

def compute_quantile(p: float, values: List[float]) -> float:
    workspace = GslRstatQuantileWorkspace()
    workspace.reset()
    workspace.add_values(values)
    quantile = workspace.get_quantile(p)
    workspace.free()
    return quantile

assert compute_quantile(0.5, [1, 2, 3, 4, 5]) == 3.0
assert compute_quantile(0.25, [10, 20, 30, 40]) == 20.0
